Lemma pch_scan : forall (k : nat) (i : Z)
    rax ra sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s6x s7x s7v s6v s5v s4v s3v s2v s1v s0v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (p : Z) (e1 e2 e3 : word) (g : bool) (j8 : list byte) (tmp : list cell),
  pch_ctx m m1 sp s7v s6v s5v s4v s3v s2v s1v s0v ra P IN E lo c1 pad7 pad2 p0 bs p e1 e2 e3 g j8 tmp ->
  pch_pure sp P IN E lo c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  p0 <= p -> 0 <= i -> p + i < p0 + Z.of_nat (length bs) -> (Z.to_nat (p0 + Z.of_nat (length bs) - (p + i)) <= k)%nat ->
  cells_size tmp = 24%nat ->
  evt rsegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
